import subprocess

# Example code to test pdfunite command
def test_pdfunite():
    try:
        # Assuming file1.pdf and file2.pdf exist in the current directory
        subprocess.run(["pdfunite", "file1.pdf", "file2.pdf", "output.pdf"], check=True)
        print("PDFs concatenated successfully.")
    except subprocess.CalledProcessError:
        print("An error occurred while concatenating PDFs.")

test_pdfunite()
